-- Database schema for SaloneVibe
CREATE TABLE IF NOT EXISTS users (
    id INT AUTO_INCREMENT PRIMARY KEY,
    email VARCHAR(255) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    display_name VARCHAR(255),
    role ENUM('user','artist','admin') NOT NULL DEFAULT 'user',
    profile_image_url VARCHAR(500),
    bio TEXT,
    location VARCHAR(255),
    created_at DATETIME NOT NULL,
    updated_at DATETIME NOT NULL
);

CREATE TABLE IF NOT EXISTS artists (
    id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    stage_name VARCHAR(255),
    genre VARCHAR(100),
    city_or_region VARCHAR(150),
    country VARCHAR(150) NOT NULL DEFAULT 'Sierra Leone',
    bio TEXT,
    notable_songs TEXT,
    image_url VARCHAR(500),
    social_youtube VARCHAR(500),
    social_spotify VARCHAR(500),
    social_instagram VARCHAR(500),
    social_facebook VARCHAR(500),
    created_at DATETIME NOT NULL,
    updated_at DATETIME NOT NULL,
    INDEX idx_artist_name (name),
    INDEX idx_artist_genre (genre),
    INDEX idx_artist_city (city_or_region)
);

CREATE TABLE IF NOT EXISTS favorites (
    id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL,
    artist_id INT NOT NULL,
    created_at DATETIME NOT NULL,
    UNIQUE KEY uniq_user_artist (user_id, artist_id),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (artist_id) REFERENCES artists(id) ON DELETE CASCADE
);


